// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 depositAmount) public {
        vm.assume(caller != address(0) && caller != address(this));
        depositAmount = bound(depositAmount, 1, address(c).balance <= type(uint256).max ? type(uint256).max : address(c).balance);
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.deposit{value: depositAmount}();
        bool success;
        address to = address(0);
        vm.prank(address(this));
        (success, ) = address(c).call(abi.encodeWithSignature("migrateTo(address)", to));
        assertTrue(success);
    }
}

